<?php
require __DIR__.'/bootstrap.php'; require_perm('invoices.view'); $me=user(); $scope=is_admin()?'':' AND (s.branch_id='.(int)require_branch().' OR s.to_branch_id='.(int)require_branch().')';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_perm('invoices.create');
  if(isset($_POST['create'])){$check=$pdo->prepare('SELECT id FROM shipments s WHERE s.id=?'.$scope);$check->execute([(int)$_POST['shipment_id']]);if(!$check->fetch()){flash('danger','Shipment is outside your branch.');redirect('shipment_invoices.php');}$subtotal=(float)$_POST['subtotal'];$discount=max(0,min($subtotal,(float)$_POST['discount_amount']));$number='INV-'.date('Y').'-'.str_pad((string)(1+(int)$pdo->query('SELECT COUNT(*) FROM shipment_invoices')->fetchColumn()),5,'0',STR_PAD_LEFT);$total=$subtotal-$discount;$pdo->prepare('INSERT INTO shipment_invoices(invoice_no,shipment_id,subtotal,discount_amount,tax_rate,tax_amount,total,issue_date,due_date,status,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$number,$_POST['shipment_id'],$subtotal,$discount,0,0,$total,$_POST['issue_date'],$_POST['due_date'],'Issued',trim($_POST['notes']),$me['id']]);flash('success',"Invoice $number created.");}
  if(isset($_POST['cancel'])){$pdo->prepare("UPDATE shipment_invoices i JOIN shipments s ON s.id=i.shipment_id SET i.status='Cancelled' WHERE i.id=?$scope")->execute([(int)$_POST['id']]);flash('success','Invoice cancelled.');} redirect('shipment_invoices.php');
}
$pdo->exec("UPDATE shipment_invoices i JOIN shipments s ON s.id=i.shipment_id SET i.status=CASE WHEN i.status='Cancelled' THEN 'Cancelled' WHEN s.paid_dxb>=(i.total+s.extra) THEN 'Paid' WHEN s.paid_dxb>0 THEN 'Partially Paid' WHEN i.due_date<CURDATE() THEN 'Overdue' ELSE 'Issued' END WHERE 1=1$scope");
$rows=$pdo->query("SELECT s.id shipment_id,s.awb,s.sender,s.receiver,s.paid_dxb,s.extra,s.total shipment_total,a.name airline,i.id inv_id,i.invoice_no,i.subtotal,i.discount_amount,i.total,i.issue_date,i.due_date,i.status,i.notes FROM shipments s JOIN airlines a ON a.id=s.airline_id LEFT JOIN shipment_invoices i ON i.id=(SELECT i2.id FROM shipment_invoices i2 WHERE i2.shipment_id=s.id AND i2.status<>'Cancelled' ORDER BY i2.id DESC LIMIT 1) WHERE 1=1$scope ORDER BY COALESCE(i.issue_date,s.shipment_date) DESC,i.id DESC,s.id DESC")->fetchAll();$ships=$pdo->query("SELECT id,awb,mark,total,receiver FROM shipments s WHERE status<>'Cancelled'$scope ORDER BY shipment_date DESC")->fetchAll();$title='Shipment invoices';require __DIR__.'/partials/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center mb-4 gap-2"><div><h1 class="h3 fw-bold mb-1">Shipment invoices</h1><p class="text-secondary mb-0">Create invoices with optional discounts and track payment status.</p></div><div><a class="btn btn-outline-primary me-1" href="invoice_payment_history.php">Payment history</a><?php if(can('invoices.create')):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#invoice"><i class="bi bi-plus-lg"></i> Create invoice</button><?php endif?></div></div>
<div class="card p-3 p-lg-4"><input class="form-control mb-3" style="max-width:420px" data-table-search placeholder="Search invoice, AWB, or customer"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Invoice</th><th>AWB / customer</th><th>Issued / due</th><th>Charges</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if($r['inv_id']):?><span class="fw-bold text-primary"><?=e($r['invoice_no'])?></span><?php else:?><span class="badge text-bg-warning">No invoice</span><?php endif?></td><td><?=e($r['awb'])?><small class="d-block text-secondary"><?=e($r['sender'])?> → <?=e($r['receiver'])?></small></td><td><?php if($r['inv_id']):?><?=app_date($r['issue_date'])?><small class="d-block text-secondary">Due <?=app_date($r['due_date'])?></small><?php else:?><span class="text-secondary">—</span><?php endif?></td><td><?php if($r['inv_id']):?>Subtotal <?=money($r['subtotal'])?><?php if((float)$r['discount_amount']>0):?><small class="d-block text-danger">Discount −<?=money($r['discount_amount'])?></small><?php endif?><?php else:?><span class="text-secondary">—</span><?php endif?></td><td class="fw-bold"><?=money($r['inv_id']?((float)$r['total']+(float)$r['extra']):((float)$r['shipment_total']+(float)$r['extra']))?></td><td><?php if($r['inv_id']):?><span class="status status-<?=strtolower(str_replace(' ','-',$r['status']))?>"><?=e($r['status'])?></span><?php else:?><span class="badge text-bg-warning">No invoice</span><?php endif?></td><td class="text-nowrap"><?php if($r['inv_id']):?><a class="btn btn-sm btn-outline-secondary" href="shipment_invoice_details.php?id=<?=$r['inv_id']?>">Details</a><a class="btn btn-sm btn-outline-primary" href="invoice_print.php?id=<?=$r['inv_id']?>" target="_blank">View</a><?php if($r['status']!=='Cancelled'&&can('invoices.create')):?><form class="d-inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['inv_id']?>"><button class="btn btn-sm btn-outline-danger" name="cancel" data-confirm="Cancel this invoice?">Cancel</button></form><?php endif?><?php else:?><?php if(can('invoices.create')):?><a class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#invoice" onclick="document.querySelector('#invoiceShipment').value=<?=$r['shipment_id']?>;document.querySelector('#invoiceShipment').dispatchEvent(new Event('change'))"><i class="bi bi-plus-lg"></i> Create invoice</a><?php endif?><?php endif?></td></tr><?php endforeach?></tbody></table></div></div>
<div class="modal fade" id="invoice"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">Create shipment invoice</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Shipment</label><select id="invoiceShipment" class="form-select mb-2" name="shipment_id" required><?php foreach($ships as $s):?><option value="<?=$s['id']?>" data-total="<?=$s['total']?>"><?=e($s['awb'].' · '.($s['mark']?:'—').' · '.$s['receiver'])?></option><?php endforeach?></select><label class="form-label">Cargo subtotal</label><input id="invoiceSubtotal" class="form-control mb-3 calc-invoice" type="number" min=".01" step=".01" name="subtotal" required><label class="form-label">Discount amount</label><input id="invoiceDiscount" class="form-control mb-2 calc-invoice" type="number" min="0" step=".01" name="discount_amount" value="0"><div class="alert alert-light border py-2 mb-3">Invoice total after discount: <strong id="invoiceNet">0.00</strong></div><div class="row"><div class="col"><label class="form-label">Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=date('Y-m-d')?>" required></div><div class="col"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></div></div><label class="form-label mt-3">Notes</label><textarea class="form-control" name="notes"></textarea></div><div class="modal-footer"><button class="btn btn-primary" name="create">Create invoice</button></div></form></div></div>
<script>const s=document.querySelector('#invoiceShipment'),a=document.querySelector('#invoiceSubtotal'),d=document.querySelector('#invoiceDiscount'),n=document.querySelector('#invoiceNet');function calc(){a.value=s.selectedOptions[0]?.dataset.total||'';n.textContent=(Math.max(0,(+a.value||0)-(+d.value||0))).toFixed(2)}s.onchange=calc;d.oninput=calc;calc();</script><?php require __DIR__.'/partials/footer.php';?>
